using System;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using ReplierDesktop;
public static class ScenePolishChecks {
 static void Check(bool b,string s){if(!b)throw new Exception(s);Console.WriteLine("PASS "+s);}
 static CommentSuggestion Row(string text){return new CommentSuggestion{Text=text,FitScore=90,GemmaFitScore=45,QwenFitScore=45,FitEligible=true,FitContextKey="stale",TiePreference=2,TieReason="stale"};}
 public static int Main(){try{var json=new JavaScriptSerializer();using(var model=new LocalModel("unused")){
 var rows=new[]{Row("결과는 좋지만 그 비용 들이 생각나네요"),Row("잘 나온 건 좋은데 쓴 돈 생각하면 아깝네요")};int calls=0;
 var polish=new ScenePolisher(model,(body,t)=>{calls++;var req=SceneMaterial.Json(json.Serialize(body));var msgs=(object[])CaptionService.Get(req,"messages");var input=(Dictionary<string,object>)SceneMaterial.Json((string)CaptionService.Get(msgs.Last(),"content"));Check(input.Count==1&&input.ContainsKey("text"),"surface edit sees only exact draft without title or transcript");return Task.FromResult(json.Serialize(new{comments=new[]{calls==1?"결과는 좋지만 그 비용이 생각나네요":rows[1].Text}}));});
 polish.Apply(rows,CancellationToken.None).GetAwaiter().GetResult();Check(rows[0].DraftText.Contains("비용 들이")&&rows[0].Text.Contains("비용이"),"debug retains original draft alongside edited sentence");Check(rows.All(r=>r.SurfaceReviewed&&!r.FitScore.HasValue&&!r.GemmaFitScore.HasValue&&!r.QwenFitScore.HasValue&&r.FitEligible==false&&r.FitContextKey==null&&r.TiePreference==0&&r.TieReason==null),"edited and unchanged reviewed drafts both require fresh independent grades");polish.Apply(rows,CancellationToken.None).GetAwaiter().GetResult();Check(calls==2,"grading retry does not repeatedly rewrite reviewed drafts");
 var pending=new[]{Row("첫 번째 초안은 그대로 유지합니다"),Row("두 번째 초안도 그대로 유지합니다")};calls=0;var broken=new ScenePolisher(model,(body,t)=>{calls++;if(calls==2)throw new System.IO.InvalidDataException("test");return Task.FromResult("{\"comments\":[\"첫 번째 문장을 고쳤습니다\"]}");});bool failed=false;try{broken.Apply(pending,CancellationToken.None).GetAwaiter().GetResult();}catch(System.IO.InvalidDataException){failed=true;}Check(failed&&pending.All(r=>!r.SurfaceReviewed&&r.FitScore==90),"partial polishing failure publishes no mixed old/new drafts or scores");
 var cancel=new CancellationTokenSource();var cancelled=new[]{Row("원래 댓글을 계속 보존합니다")};var interrupted=new ScenePolisher(model,(body,t)=>{cancel.Cancel();return Task.FromResult("{\"comments\":[\"문장을 조금 다듬어 보았습니다\"]}");});failed=false;try{interrupted.Apply(cancelled,cancel.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){failed=true;}Check(failed&&!cancelled[0].SurfaceReviewed&&cancelled[0].FitScore==90,"cancellation before commit preserves original draft and assessment");
 }return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
